package io.fireflysoftware.commons.ecm.core.signing;
import java.nio.file.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SigningPolicyCustodySchemaTest {
    static final Path ROOT=Path.of(System.getProperty("core.signing.source"));
    static final Path SQL=ROOT.resolve("core-common-document-mgmt-models/src/main/resources/db/optional/document-signing/V9__Signing_Policy_Custody.sql");
    String sql()throws Exception{assertTrue(Files.isRegularFile(SQL),"Mandatory optional forward policy custody installer source is absent");return Files.readString(SQL);}
    @Test void sourceRequiresTwoWayScopedGraphAndAppendOnlyCustody()throws Exception{var s=sql();for(String token:new String[]{"UNIQUE(tenant_id,event_id)","UNIQUE(tenant_id,operation_id,phase)","FOREIGN KEY(tenant_id,operation_id,resource_tenant_id)","FOREIGN KEY(resource_tenant_id,event_id)","DEFERRABLE INITIALLY DEFERRED","CREATE CONSTRAINT TRIGGER signing_policy_reverse_graph","BEFORE UPDATE OR DELETE ON document_signing.policy_custody"})assertTrue(s.contains(token),token);}
    @Test void privateTraceEncoderPreservesOpaqueUtf8AndUtf16Bounds()throws Exception{var s=sql();for(String token:new String[]{"CORE_SIGNING_POLICY_TRACE","INITIAL_AUTHORIZATION","AFTER_STORAGE_REVALIDATION","RESERVE_ADMISSION","PREPARED_ADMISSION","pg_catalog.int4send(1)","pg_catalog.int4send(0)","units>256","codepoint>65535","codepoint BETWEEN 127 AND 159","pg_catalog.convert_to(value,'UTF8')"})assertTrue(s.contains(token),token);assertFalse(s.contains("firefly_audit_private.canonical_text(value"));}
    @Test void actualStoredBusinessAndTraceDigestsAreRecomputedBeforeOriginalCanonicalBridge()throws Exception{var s=sql();assertTrue(s.contains("CORE_SIGNING_EFFECT_V2"));assertTrue(s.contains("CORE_SIGNING_EFFECT"));assertTrue(s.contains("pg_catalog.int4send(3)"));assertTrue(s.contains("c.business_digest IS DISTINCT FROM business_digest"));assertTrue(s.contains("c.trace_digest IS DISTINCT FROM trace_digest"));assertTrue(s.indexOf("c.trace_digest IS DISTINCT FROM trace_digest")<s.indexOf("PERFORM firefly_audit.document_signing_require_audit"));assertTrue(s.contains("operation.reservation_trace_digest"));assertTrue(s.contains("operation.prepared_trace_digest"));}
    @Test void oldRowsStayUnchangedButCannotSilentlyResumeOrInsertLegacyProtocol()throws Exception{var s=sql();assertTrue(s.contains("NEW.evidence_protocol IS DISTINCT FROM 3"));assertTrue(s.contains("OLD.evidence_protocol IS DISTINCT FROM 3"));assertFalse(s.contains("UPDATE document_signing.operation SET"));assertFalse(s.contains("DEFAULT 3"));assertFalse(s.contains("CREATE ROLE"));}
    @Test void narrowOwnerPrerequisitesAndTemporaryReferencesAreExplicit()throws Exception{var s=sql();for(String token:new String[]{"pg_catalog.pg_has_role(current_user,'firefly_audit_guard','SET')","pg_catalog.pg_has_role(current_user,'document_signing_guard','SET')","firefly_audit_private.require_record_hash(firefly_audit.audit_event)","search_path=pg_catalog","GRANT REFERENCES(resource_tenant_id,event_id)","REVOKE REFERENCES(resource_tenant_id,event_id)","REVOKE ALL ON document_signing.policy_custody FROM PUBLIC,firefly_audit_writer,firefly_audit_reader","GRANT SELECT,INSERT ON document_signing.policy_custody TO firefly_audit_writer"})assertTrue(s.contains(token),token);assertFalse(s.contains("GRANT SELECT ON firefly_audit.audit_event"));assertFalse(s.contains("ROW LEVEL SECURITY"));}
    @Test void existingAuditRlsAndBridgeBytesMustBeAttestedBeforeNewRuntimePrivileges()throws Exception{var s=sql();assertTrue(s.contains("Original audit RLS policy graph required"));assertTrue(s.contains("relrowsecurity"));assertTrue(s.contains("relforcerowsecurity"));assertTrue(s.contains("audit_scoped_read"));assertTrue(s.contains("audit_scoped_insert"));assertTrue(s.contains("audit_head_cas"));assertTrue(s.contains("bridge.prosrc"));assertTrue(s.indexOf("Original audit RLS policy graph required")<s.indexOf("GRANT REFERENCES(resource_tenant_id,event_id)"));}

}
